import {pair,programs,days,trips,albums,mealsFor,weekday,scheduleFor} from './data.js';
import {assets} from './assets.js';
let lang='en';
let selectedDay=24;
let mealDay=24;
let modal=null;
let returnFocus=null;
const app=document.querySelector('#app');
const viewer=document.querySelector('#viewer');
const t=(en,es)=>lang==='en'?en:es;
const local=value=>value[lang];
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=()=>location.hash.slice(1)||'welcome';
const paths={home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18m-13 4h2m4 0h2m-8 3h2"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m14 5-7 7 7 7M7 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M3 3l6 6m12-6-6 6M3 21l6-6m12 6-6-6"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v2m0 18v2M1 12h2m18 0h2M4 4l1.5 1.5m13 13L20 20M4 20l1.5-1.5m13-13L20 4"/>',announcement:'<path d="m3 10 16-6v15L3 14zm4 5 2 6h4l-2-5M22 8v7"/>',meal:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v19M19 3c-5 4-5 10 0 10V3v19"/>',bus:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="M3 13h18M7 19v2m10-2v2M8 5v8m8-8v8M6 16h1m10 0h1"/>',photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m3 18 6-6 4 4 3-3 5 5"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18h2a2 2 0 0 0 1-4c-2-1-1-3 1-3h2c5 0 3-11-6-11Z"/><circle cx="7" cy="10" r=".6"/><circle cx="11" cy="7" r=".6"/><circle cx="16" cy="8" r=".6"/>',yoga:'<circle cx="12" cy="5" r="2"/><path d="m8 10 4-2 4 2m-4-2v7m-4-5-4 4m12-4 4 4m-8 1-6 5h12z"/>',computer:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M12 16v5m-5 0h10M7 8l2 2-2 2m5 0h4"/>',billiards:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="9" r="2"/><ellipse cx="12" cy="14" rx="3" ry="2.5"/>',fitness:'<path d="M8 12h8M4 7v10m4-12v14m8-14v14m4-12v10M2 10v4m20-4v4"/>',leaf:'<path d="M20 3C9 2 2 9 6 16s16 2 14-13ZM4 21 17 8M9 16v-5m0 5h5"/>',music:'<path d="M9 18V5l11-2v13M9 9l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',puzzle:'<path d="M4 4h6c-2 5 6 5 4 0h6v6c-5-2-5 6 0 4v6h-6c2-5-6-5-4 0H4v-6c5 2 5-6 0-4z"/>',racket:'<ellipse cx="14" cy="9" rx="6" ry="7" transform="rotate(35 14 9)"/><path d="m10 15-6 7m-1-1 3 2M10 6l8 5m-7 2 5-8"/>',bingo:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 3v18m6-18v18M3 15h18"/><circle cx="12" cy="12" r="1"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m12 8-3 6 4 3 1 5M12 8l4 5 4 1M9 14l-4 7m5-11-5 3"/>',cup:'<path d="M4 8h12v9a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4ZM16 9h2a3 3 0 0 1 0 6h-2M7 2v2m5-2v2"/>'};
function icon(name){return `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||paths.sun}</svg>`;}
function mark(){return `<img class="mark" src="${assets.logos.mann}" alt="" width="1228" height="962">`;}
function art(item,variant=0){
 const colors={rose:['#fae4eb','#d97796'],lavender:['#e9e5fb','#8e80c3'],mint:['#e0f1e5','#6ca589'],sky:['#e0f1f8','#78abc5'],peach:['#f9e8d8','#c7956c'],yellow:['#fff2ce','#d2a645']};
 const [bg,accent]=colors[item.color]||colors.sky;
 return `<svg class="artwork" viewBox="0 0 360 220" preserveAspectRatio="xMidYMid slice" role="img" aria-label="${esc(t('Illustration: ','Ilustración: ')+local(item.name))}"><rect width="360" height="220" fill="${bg}"/><circle cx="${variant%2?60:300}" cy="35" r="90" fill="${accent}" opacity=".14"/><path d="M-20 200Q90 100 180 200T390 150V240H-20" fill="${accent}" opacity=".18"/><circle cx="180" cy="105" r="65" fill="#ffffff" opacity=".7"/><g transform="translate(${145+variant*2} 70) rotate(${variant*6-3} 35 35) scale(3)" fill="none" stroke="#0f4d90" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round">${paths[item.icon]||paths.photo}</g><g fill="${accent}"><circle cx="72" cy="72" r="7"/><circle cx="288" cy="153" r="5"/><path d="m282 72 5 8 9 1-7 6 2 9-9-4-8 4 1-9-6-6 9-1z"/><rect x="65" y="155" width="12" height="12" rx="3" transform="rotate(20 70 160)"/></g></svg>`;
}
function language(){return `<div class="language" role="group" aria-label="${t('Language','Idioma')}"><button data-lang="en" lang="en" aria-label="English" aria-pressed="${lang==='en'}">ENG</button><button data-lang="es" lang="es" aria-label="Español" aria-pressed="${lang==='es'}">ESP</button></div>`;}
function time(minutes){const hour=Math.floor(minutes/60);return `${hour%12||12}:${String(minutes%60).padStart(2,'0')} ${hour<12?'AM':'PM'}`;}
function date(day){return new Intl.DateTimeFormat(lang==='en'?'en-US':'es-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(new Date(2025,8,day,12));}
function session(s){return `${local(days)[s.day]}${t('s','')}, ${time(s.start)} – ${time(s.end)}`;}
function title(heading,sub=''){return `<div class="intro"><h1 id="page-title" tabindex="-1">${esc(heading)}</h1>${sub?`<p class="muted">${sub}</p>`:''}</div>`;}
function render(focus=false){
 const r=route();const primary=r==='home'?'home':r==='information'?'information':r==='welcome'?'': 'center';
 const parent=r.startsWith('program/')?'programs':r.startsWith('album/')?'albums':['programs','calendar','meals','trips','albums'].includes(r)?'center':null;
 let content=r==='welcome'?welcome():r==='home'?home():r==='center'?center():r==='programs'?programList():r.startsWith('program/')?programDetail(r.split('/')[1]):r==='calendar'?calendarPage():r==='meals'?mealPage():r==='trips'?tripPage():r==='albums'?albumPage():r.startsWith('album/')?albumDetail(r.split('/')[1]):r==='information'?information():welcome();
 document.documentElement.lang=lang;document.querySelector('.skip-link').textContent=t('Skip to content','Saltar al contenido');
 app.innerHTML=`<header class="brand-header"><a class="header-inner" href="#welcome" aria-label="${t('Mann Older Adult Center — return to language selection','Mann Older Adult Center — volver a la selección de idioma')}">${mark()}<div class="brand-name">Mann<span class="screen-reader"> </span><small>Older Adult Center</small></div></a></header><main class="page ${r==='welcome'?'landing-page':''}" id="main" tabindex="-1"><div class="toolbar">${parent?`<a class="back" href="#${parent}">${icon('back')}${t('Back','Atrás')}</a>`:r==='home'?`<div class="greeting">${icon('sun')}${t('Hello!','¡Hola!')}</div>`:r==='center'?`<span class="eyebrow" style="margin:0">${t('Your community','Su comunidad')}</span>`:''}${r==='welcome'?'':language()}</div>${content}</main><nav class="bottom-nav" aria-label="${t('Primary navigation','Navegación principal')}">${[['home','home','Home','Inicio'],['center','people','My Center','Mi Centro'],['information','info','Information','Información']].map(([id,ic,en,es])=>`<a href="#${id}" ${primary===id?'aria-current="page"':''}>${icon(ic)}<span>${t(en,es)}</span></a>`).join('')}</nav>`;
 document.title=`${document.querySelector('h1')?.textContent||'Welcome'} | Mann Older Adult Center`;
 if(focus){window.scrollTo(0,0);document.querySelector('#page-title')?.focus({preventScroll:true});}
}
function welcome(){return `<section class="landing"><img class="landing-composition" src="${assets.landing[0]}" alt="" aria-hidden="true" width="880" height="1912" decoding="async"><h1 id="page-title" tabindex="-1"><span lang="en">Welcome!</span><br><span lang="es">¡Bienvenidos!</span></h1><div class="welcome-art" aria-hidden="true"><span class="welcome-mark">${mark()}</span></div><p class="address"><strong>Mann Older Adult Center</strong><br>3201 North 5th St.<br>Philadelphia PA 19140<br><a href="tel:+12155311983">(215) 531-1983</a></p><p class="language-prompt"><span lang="en">Select Language</span><br><span lang="es">Selecciona el idioma</span></p><div class="landing-ctas"><button class="button" data-enter="en" lang="en">ENGLISH ${icon('arrow')}</button><button class="button yellow" data-enter="es" lang="es">ESPAÑOL ${icon('arrow')}</button></div></section>`;}
function scheduleList(day){const list=scheduleFor(day);return list.length?`<ul class="schedule">${list.map(s=>`<li><time>${time(s.start)}</time>${s.id?`<a href="#program/${s.id}">${esc(local(s.name))}</a>`:`<span>${esc(local(s.name))}</span>`}</li>`).join('')}</ul>`:`<p>${t('The center is closed.','El centro está cerrado.')}</p>`;}
function home(){const m=mealsFor(24);return `<section class="home-date"><p class="eyebrow">${t('Today is','Hoy es')}</p><h1 id="page-title" tabindex="-1">${t('Wednesday,','Miércoles,')}<br><span class="date-number">${t('September 24, 2025','24 de septiembre de 2025')}</span></h1></section><div class="home-stack"><section class="card announcement"><div class="card-title"><span class="icon-box">${icon('announcement')}</span><h2>${t('Announcements','Avisos de hoy')}</h2></div><ul><li>${t('Chair Yoga meets Tuesdays, 10:30 AM – 11:30 AM.','La clase de Yoga en silla se reúne los martes, de 10:30 AM a 11:30 AM.')}</li><li>${t('Don’t forget: Flu shots are available next Thursday. Sign up at the front desk.','No olvides: Vacunas contra la gripe disponibles el próximo jueves. Regístrate en la recepción.')}</li></ul></section><section class="card programs-today"><div class="card-title"><span class="icon-box">${icon('people')}</span><h2>${t('Today’s Programs','Programas de hoy')}</h2></div>${scheduleList(24)}</section><section class="card"><div class="card-title"><span class="icon-box yellow">${icon('meal')}</span><h2>${t('Today’s Meals','Comida del Día')}</h2></div><div class="meal-row"><p><strong>${t('Hot','Caliente')}</strong>${esc(local(m.hot))} - ${m.hotCount}</p></div><div class="meal-row"><p><strong>${t('Cold','Fría')}</strong>${esc(local(m.cold))} - ${m.coldCount}</p></div></section></div>`;}
function center(){return title(t('My Center','Mi Centro'),t('A place to connect, learn, and enjoy your day.','Un lugar para conectar, aprender y disfrutar del día.'))+`<div class="category-list">${[['calendar','calendar','lavender','Monthly Calendar','Calendario mensual','September 2025','Septiembre 2025'],['programs','people','rose','Our Programs','Nuestros programas','Find something you enjoy','Encuentre algo que le guste'],['meals','meal','yellow','Meals','Comidas','September 2025','Septiembre 2025'],['trips','bus','mint','Monthly Trips','Viajes del mes','Outings and upcoming events','Excursiones y próximos eventos'],['albums','photo','sky','Photo Albums','Álbumes de fotos','Moments from our community','Momentos de nuestra comunidad']].map(([id,ic,color,en,es,subEn,subEs])=>`<a class="category ${color}" href="#${id}"><span class="icon-box">${icon(ic)}</span><div><h2>${t(en,es)}</h2><p>${t(subEn,subEs)}</p></div>${icon('arrow')}</a>`).join('')}</div>`;}
function programList(){return title(t('Our Programs','Nuestros programas'),t('Make time for something you love.','Dedique tiempo a lo que le gusta.'))+`<div class="program-grid">${programs.map(p=>`<a class="program-card" href="#program/${p.id}">${art(p)}<div class="program-info"><h2>${esc(local(p.name))}</h2><p>${p.sessions.map(s=>local(days)[s.day]).join(' · ')}</p><span class="card-link-label">${t('View program','Ver programa')}${icon('arrow')}</span></div></a>`).join('')}</div>`;}
function programDetail(id){const p=programs.find(p=>p.id===id);if(!p)return programList();return title(local(p.name))+`<div class="detail-layout"><div class="poster-wrap">${programPoster(p)}</div><div class="detail-copy"><section><h2>${t('When','Cuándo')}</h2><ul>${p.sessions.map(s=>`<li>${session(s)}</li>`).join('')}</ul></section>${p.instructor?`<section><h2>${t('Instructor','Instructor/a')}</h2><p>${esc(local(p.instructor))}</p></section>`:''}<section><h2>${t('About the Class','Sobre la clase')}</h2><p>${esc(local(p.description))}</p></section><section><h2>${t('Where','Dónde')}</h2><p>Mann Older Adult Center<br>3201 N. 5th St.<br>Philadelphia, PA 19140</p></section><section><h2>${t('Contact','Contacto')}</h2><a href="tel:+12155311983">215-531-1983</a></section></div></div>`;}
function programPoster(p){return `<div class="poster">${art(p)}<div class="poster-text"><p class="eyebrow">Mann Older Adult Center</p><h2>${esc(local(p.name))}</h2>${p.sessions.map(s=>`<p>${session(s)}</p>`).join('')}</div></div>`;}
// Additional destinations are composed below from the same bilingual source data.
function calendarPage(){return title(t('Monthly Calendar','Calendario mensual'))+calendarContent();}
function calendarContent(){return `<section class="card calendar-card"><div class="calendar-heading"><h2>${t('September 2025','Septiembre 2025')}</h2>${icon('calendar')}</div>${dayGrid(selectedDay,'day')}<div class="daily-panel" aria-live="polite">${titleSmallDate(selectedDay)}${scheduleList(selectedDay)}</div></section>`;}
function titleSmallDate(day){return `<h3>${date(day)}</h3>`;}
function dayGrid(selected,action){return `<p class="calendar-instruction">${t('Choose a date to see the day’s information.','Elija una fecha para ver la información del día.')}</p><div class="month-grid">${t(['M','T','W','T','F','S','S'],['L','M','M','J','V','S','D']).map((s,i)=>`<span class="day-label" aria-label="${local(days)[(i+1)%7]}">${s}</span>`).join('')}${Array.from({length:30},(_,i)=>{const d=i+1,closed=d===1||[0,6].includes(weekday(d));return `<button class="day ${d===24?'today':''} ${closed?'closed':''}" data-action="${action}" data-day="${d}" ${d===24?'aria-current="date"':''} aria-label="${date(d)}${d===24?t(', today',', hoy'):''}${closed?t(', center closed',', centro cerrado'):t(', activities scheduled',', actividades programadas')}" aria-pressed="${d===selected}"><span>${d}</span><span class="day-dot" aria-hidden="true" style="visibility:${closed?'hidden':'visible'}"></span></button>`;}).join('')}</div><div class="calendar-key"><span><i class="key-today"></i>${t('Today: 24','Hoy: 24')}</span><span><i class="key-selected"></i>${t('Selected','Seleccionado')}</span><span><i class="day-dot"></i>${t('Activities','Actividades')}</span></div>`;}
function mealPage(){const m=mealsFor(mealDay),open=scheduleFor(mealDay).length>0;return title(t('Meals','Comidas'))+`<section class="card calendar-card"><h2>${t('September 2025','Septiembre 2025')}</h2>${dayGrid(mealDay,'meal-day')}<div class="daily-panel meal-detail" aria-live="polite"><h3>${date(mealDay)}${open?' · 12:00 PM':''}</h3>${open?`<div class="meal-row"><p><strong>${t('Hot','Caliente')}</strong>${esc(local(m.hot))} - ${m.hotCount}</p></div><div class="meal-row"><p><strong>${t('Cold','Fría')}</strong>${esc(local(m.cold))} - ${m.coldCount}</p></div>`:`<p>${t('The center is closed.','El centro está cerrado.')}</p>`}</div></section>`;}

function tripPage(){return title(t('Monthly Trips','Viajes del mes'))+`<section class="card"><p class="eyebrow">${t('September 2025','Septiembre 2025')}</p><h2>${t('Upcoming Events','Próximos Eventos')}</h2>${tripList()}</section>`;}
function tripList(){return `<ul class="trip-list">${trips.map(tr=>`<li><div class="date-badge"><span>SEP</span><strong>${tr.day}</strong></div><div class="trip-copy"><p class="trip-weekday">${local(days)[weekday(tr.day)]}</p><p>${esc(local(tr.name))}</p></div></li>`).join('')}</ul><h3 style="margin-top:26px">${t('Future Event Reminders','Recordatorios de eventos futuros')}</h3><ul><li>${t('Oct – Senior Strut (date TBD)','Oct – Senior Strut (fecha por determinar)')}</li><li>${t('Dec – Senior Gala 2025 (date TBD)','Dic – Gala de mayores 2025 (fecha por determinar)')}</li></ul>`;}
function albumPhotos(a){return assets.albums[a.id]||[];}
function photoCount(count){return `${count} ${t(count===1?'photo':'photos',count===1?'foto':'fotos')}`;}
function photoAlt(a,index){return `${local(a.name)} — ${t('photo','foto')} ${index+1}`;}
function albumPage(){return title(t('Photo Albums','Álbumes de fotos'))+`<div class="album-grid">${albums.map(a=>{const photos=albumPhotos(a);return `<a class="album-card" href="#album/${a.id}">${photos.length?`<img class="album-cover" src="${photos[a.id==='ribbon'?1:0]}" alt="${esc(t('Album: ','Álbum: ')+local(a.name))}" loading="lazy" decoding="async">`:`<div class="album-empty-cover">${t('Photos pending','Fotos pendientes')}</div>`}<h2>${esc(local(a.name))}</h2><p>${photos.length?photoCount(photos.length):t('Not yet available','Aún no disponibles')}</p></a>`;}).join('')}</div>`;}
function albumDetail(id){const a=albums.find(a=>a.id===id);if(!a)return albumPage();const photos=albumPhotos(a);return title(local(a.name),photos.length?photoCount(photos.length):'')+(photos.length?`<div class="gallery-grid">${photos.map((src,i)=>`<button class="gallery-item" data-action="image" data-id="${id}" data-index="${i}" aria-label="${esc(t('View photo','Ver foto')+' '+(i+1)+' — '+local(a.name))}"><img src="${src}" alt="${esc(photoAlt(a,i))}" loading="lazy" decoding="async"></button>`).join('')}</div>`:`<div class="card empty-album"><h2>${t('Photos not available yet','Fotos aún no disponibles')}</h2><p>${t('Photos for this album have not been supplied yet.','Todavía no se han proporcionado fotos para este álbum.')}</p><a class="button secondary" href="#albums">${t('Back to albums','Volver a los álbumes')}</a></div>`);}
function information(){return title(t('Center Information','Información del Centro'))+`<div class="info-grid"><section class="card"><h2>Mann Older Adult Center</h2><p>3201 N. 5th Street<br>Philadelphia, PA 19140</p><p><strong>${t('Phone','Teléfono')}:</strong><br><a href="tel:+12155311983">(215) 531-1983</a></p><p><strong>${t('Email','Correo electrónico')}:</strong><br><a style="overflow-wrap:anywhere" href="mailto:Gisel.Cruz-Lopez@phila.gov">Gisel.Cruz-Lopez@phila.gov</a></p></section><section class="card"><h2>${t('Center Hours','Horario del Centro')}</h2><p>${t('Monday – Friday','Lunes a Viernes')}<br>8:00 AM – 4:00 PM</p></section><section class="card"><h2>${t('Staff','Personal')}</h2><dl class="staff">${[['Director','Directora','Kelly Williams-Crocker'],['Office Clerk','Secretaria','Gisel Cruz-Lopez'],['Social Worker','Trabajadora Social','Maria M. Bossard'],['Program Coordinator','Coordinadora de Programas','Dejah Octavia Bryan'],['Care Taker','Encargado','Dominic Gunter'],['Food Service Worker','Trabajadora de Servicio de Alimentos','Maria Martinez']].map(([en,es,name])=>`<div><dt>${t(en,es)}</dt><dd>${name}</dd></div>`).join('')}</dl></section><section class="card"><h2>${t('Membership','Membresía')}</h2><ul><li>${t('Must be 60+ years old','Debe tener 60 años o más')}</li><li>${t('Bring ID and proof of income (SSI, pension, or bank statements)','Traer identificación y comprobante de ingresos (SSI, pensión o estados de cuenta bancarios)')}</li><li>${t('List of medications & primary care doctor info','Lista de medicamentos e información de su médico primario')}</li><li>${t('Emergency contact','Contacto de emergencia')}</li><li>${t('$10 annual registration (cash only)','Cuota anual de $10 (solo en efectivo)')}</li></ul></section><section class="card wide"><h2>${t('Sponsors / Partners','Patrocinadores / Socios')}</h2><div class="partner-list"><img class="partner-logo parks" src="${assets.logos.parks}" alt="Philadelphia Parks & Recreation"><img class="partner-logo" src="${assets.logos.philabundance}" alt="Philabundance"><img class="partner-logo wellcare" src="${assets.logos.wellcare}" alt="Wellcare">${assets.logos.pca?`<img class="partner-logo pca" src="${assets.logos.pca}" alt="PCA — Philadelphia Corporation for Aging">`:`<span class="partner-text">PCA<br>Philadelphia Corporation for Aging</span>`}</div></section></div><p style="text-align:center;margin-top:28px;font-weight:600">${t('We look forward to seeing you at the Mann Center!','Esperamos verlo en el Centro Mann!')}</p>`;}
function renderModal(){
 if(!modal)return;
 const a=albums.find(a=>a.id===modal.id),photos=albumPhotos(a);
 viewer.innerHTML=`<div class="dialog-header"><h2 id="dialog-title">${esc(local(a.name))}</h2><button class="close" data-action="close" autofocus>${icon('close')}${t('Close','Cerrar')}</button></div><div class="dialog-body"><div class="gallery-view"><img class="focused-photo" src="${photos[modal.index]}" alt="${esc(photoAlt(a,modal.index))}" draggable="false"><p class="photo-position" aria-live="polite">${t('Photo','Foto')} ${modal.index+1} / ${photos.length}</p><div class="gallery-controls"><button class="button secondary" data-action="prev" ${modal.index===0?'disabled':''} aria-label="${t('Previous photo','Foto anterior')}">${icon('back')}<span>${t('Previous','Anterior')}</span></button><button class="button secondary" data-action="next" ${modal.index===photos.length-1?'disabled':''} aria-label="${t('Next photo','Foto siguiente')}"><span>${t('Next','Siguiente')}</span>${icon('arrow')}</button></div></div></div>`;
}
function movePhoto(delta,focusAction){
 if(!modal)return;
 const count=albumPhotos(albums.find(a=>a.id===modal.id)).length;
 const next=Math.max(0,Math.min(count-1,modal.index+delta));
 if(next===modal.index)return;
 const focused=document.activeElement?.dataset;
 const restore=focusAction||focused?.action;
 const restoreLang=focused?.lang;
 modal.index=next;renderModal();
 const target=restoreLang?viewer.querySelector('[data-lang="'+restoreLang+'"]'):viewer.querySelector('[data-action="'+restore+'"]');
 (target&&!target.disabled?target:viewer.querySelector('.close')).focus({preventScroll:true});
}
function openModal(value,trigger){modal=value;returnFocus=trigger;renderModal();viewer.showModal();document.body.style.overflow='hidden';viewer.querySelector('.close').focus();}
function closeModal(){viewer.close();}
viewer.addEventListener('close',()=>{modal=null;document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else document.querySelector('#page-title')?.focus({preventScroll:true});});
viewer.addEventListener('keydown',e=>{
 if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();movePhoto(e.key==='ArrowRight'?1:-1);return;}
 if(e.key!=='Tab')return;
 const controls=[...viewer.querySelectorAll('button:not(:disabled),a[href],[tabindex="0"]')].filter(el=>el.getClientRects().length);
 const first=controls[0],last=controls.at(-1);
 if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
});
let swipeStart=null;
viewer.addEventListener('pointerdown',e=>{if(e.target.closest('.focused-photo'))swipeStart={x:e.clientX,y:e.clientY,id:e.pointerId};});
viewer.addEventListener('pointerup',e=>{if(!swipeStart||e.pointerId!==swipeStart.id)return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy)*1.5)movePhoto(dx<0?1:-1);});
viewer.addEventListener('pointercancel',()=>{swipeStart=null;});
viewer.addEventListener('click',e=>{if(e.target===viewer){const b=viewer.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeModal();}});
document.addEventListener('click',e=>{
 const skip=e.target.closest('.skip-link');if(skip){e.preventDefault();document.querySelector('#main').focus();return;}
 const enter=e.target.closest('[data-enter]');if(enter){lang=enter.dataset.enter;location.hash='home';if(route()==='home')render();return;}
 const lb=e.target.closest('[data-lang]');if(lb){lang=lb.dataset.lang;const y=window.scrollY;const triggerAction=returnFocus?.dataset.action;const triggerId=returnFocus?.dataset.id;const triggerIndex=returnFocus?.dataset.index;const triggerType=returnFocus?.dataset.type;render();window.scrollTo(0,y);if(modal){returnFocus=[...document.querySelectorAll('main [data-action]')].find(el=>el.dataset.action===triggerAction&&el.dataset.id===triggerId&&el.dataset.index===triggerIndex&&el.dataset.type===triggerType);const sy=viewer.scrollTop;renderModal();viewer.scrollTop=sy;viewer.querySelector(`[data-lang="${lang}"]`).focus({preventScroll:true});}else document.querySelector(`[data-lang="${lang}"]`).focus({preventScroll:true});return;}
 const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;
 if(a==='close'){closeModal();return;}
 if(a==='day'||a==='meal-day'){const y=window.scrollY;const day=Number(el.dataset.day);if(a==='day')selectedDay=day;else mealDay=day;render();window.scrollTo(0,y);document.querySelector('[data-action="'+a+'"][data-day="'+day+'"]').focus({preventScroll:true});return;}
 if(a==='prev'||a==='next'){movePhoto(a==='next'?1:-1,a);return;}
 if(a==='image')openModal({type:a,id:el.dataset.id,index:Number(el.dataset.index||0)},el);
});
window.addEventListener('hashchange',()=>{if(viewer.open)viewer.close();render(true);});
render();

